import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

void main() {
  group('DashboardPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();
    final MockSettingsRepository mockSettingsRepository = MockSettingsRepository();

    late Widget dashboardWidget;

    setUp(() {
      dashboardWidget = buildWidget(
        providers: [
          Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          Provider<NewsRepository>.value(value: mockNewsRepository),
          Provider<SettingsRepository>.value(value: mockSettingsRepository),
        ],
        child: const DashboardPage(),
      );

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) async => const CurrencyPage(items: [], page: 0, hasMore: false),
      );
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => []);
      when(mockSettingsRepository.readThemeMode()).thenReturn(AppThemeMode.system);
    });

    testWidgets('should display dashboard title', (WidgetTester tester) async {
      await tester.pumpWidget(dashboardWidget);
      await tester.pumpAndSettle();

      expect(find.text('Дашборд'), findsOneWidget);
    });

    testWidgets('should show CircularProgressIndicator while loading',
        (WidgetTester tester) async {
      // Create a Completer to control when futures complete
      final Completer<CurrencyPage> currencyCompleter =
          Completer<CurrencyPage>();
      final Completer<List<NewsModel>> newsCompleter =
          Completer<List<NewsModel>>();

      // Override mocks for this test
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) => currencyCompleter.future,
      );
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer(
        (_) => newsCompleter.future,
      );

      await tester.pumpWidget(dashboardWidget);
      await tester.pump();

      // Should show progress indicator while loading
      expect(find.byType(CircularProgressIndicator), findsOneWidget);

      // Complete both futures
      currencyCompleter.complete(const CurrencyPage(items: [], page: 0, hasMore: false));
      newsCompleter.complete([]);
      await tester.pumpAndSettle();

      // Progress indicator should be gone
      expect(find.byType(CircularProgressIndicator), findsNothing);
    });

    testWidgets('should display empty state with headings when data is loaded',
        (WidgetTester tester) async {
      await tester.pumpWidget(dashboardWidget);
      await tester.pumpAndSettle();

      // Should show "Валюты" and "Новости" headings even with empty lists
      expect(find.text('Валюты'), findsOneWidget);
      expect(find.text('Новости'), findsOneWidget);
    });

    testWidgets('should display currency cards when data is available',
        (WidgetTester tester) async {
      final List<CurrencyModel> currencies = [
        const CurrencyModel(
          id: 1,
          name: 'US Dollar',
          symbol: 'USD',
          value: 90.50,
          previousValue: 90.00,
          nominal: 100,
        ),
      ];

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) async => CurrencyPage(items: currencies, page: 0, hasMore: false),
      );

      await tester.pumpWidget(dashboardWidget);
      await tester.pumpAndSettle();

      expect(find.byType(CurrencyCard), findsOneWidget);
    });

    testWidgets('should display news cards when data is available',
        (WidgetTester tester) async {
      final List<NewsModel> news = [
        const NewsModel(
          title: 'Test News',
          link: 'http://test.com/news/1',
          date: null,
        ),
      ];

      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer(
        (_) async => news,
      );

      await tester.pumpWidget(dashboardWidget);
      await tester.pumpAndSettle();

      expect(find.byType(NewsCard), findsOneWidget);
    });
  });
}
